  1→// Package compact converts full.jsonl transcripts into a normalized,
  2→// compact transcript.jsonl format. Only shared formatting is contained here.
  3→package compact
  4→
  5→import (
  6→	"bufio"
  7→	"bytes"
  8→	"encoding/json"
  9→	"fmt"
 10→	"io"
 11→	"strings"
 12→
 13→	"github.com/entireio/cli/cmd/entire/cli/textutil"
 14→	"github.com/entireio/cli/cmd/entire/cli/transcript"
 15→)
 16→
 17→// Options provides metadata fields written to every output line.
 18→type Options struct {
 19→	Agent      string // e.g. "claude-code"
 20→	CLIVersion string // e.g. "0.42.0"
 21→	StartLine  int    // checkpoint_transcript_start (0 = no truncation)
 22→}
 23→
 24→// compactMeta holds pre-computed JSON fragments for fields that are identical
 25→// on every output line, avoiding repeated marshaling.
 26→type compactMeta struct {
 27→	v          json.RawMessage
 28→	agent      json.RawMessage
 29→	cliVersion json.RawMessage
 30→}
 31→
 32→func newCompactMeta(opts Options) compactMeta {
 33→	return compactMeta{
 34→		v:          mustMarshal(1),
 35→		agent:      mustMarshal(opts.Agent),
 36→		cliVersion: mustMarshal(opts.CLIVersion),
 37→	}
 38→}
 39→
 40→// Compact converts a full.jsonl transcript into the condensed transcript.jsonl format.
 41→//
 42→// The output format puts version, agent, and cli_version on every line,
 43→// merges streaming assistant fragments with the same message ID, and inlines
 44→// tool results into the preceding assistant's tool_use blocks:
 45→//
 46→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
 47→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[{"type":"text","text":"..."},{"type":"tool_use","id":"...","name":"...","input":{...},"result":{"output":"...","status":"..."}}]}
 48→func Compact(content []byte, opts Options) ([]byte, error) {
 49→	truncated := transcript.SliceFromLine(content, opts.StartLine)
 50→	if truncated == nil {
 51→		truncated = []byte{}
 52→	}
 53→
 54→	if isOpenCodeFormat(truncated) {
 55→		return compactOpenCode(truncated, opts)
 56→	}
 57→
 58→	return compactJSONL(truncated, opts)
 59→}
 60→
 61→// droppedTypes are JSONL entry types that carry no parser-relevant data.
 62→var droppedTypes = map[string]bool{
 63→	"progress":              true,
 64→	"file-history-snapshot": true,
 65→	"queue-operation":       true,
 66→	"system":                true,
 67→}
 68→
 69→// userAliases maps JSONL type/role values to the canonical "user" kind.
 70→// Covers Claude Code ("user", "human") and Cursor ("user" via "role" field).
 71→var userAliases = map[string]bool{
 72→	transcript.TypeUser: true,
 73→	"human":             true,
 74→}
 75→
 76→// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
 77→// JSONL transcript line. It checks the "type" field, then falls back to "role".
 78→// Returns "" for unrecognised or dropped entries.
 79→func normalizeKind(raw map[string]json.RawMessage) string {
 80→	kind := unquote(raw["type"])
 81→	if kind == "" {
 82→		kind = unquote(raw["role"])
 83→	}
 84→
 85→	if droppedTypes[kind] {
 86→		return ""
 87→	}
 88→	if userAliases[kind] {
 89→		return transcript.TypeUser
 90→	}
 91→	if kind == transcript.TypeAssistant {
 92→		return transcript.TypeAssistant
 93→	}
 94→	return ""
 95→}
 96→
 97→// linePreprocessor transforms a parsed JSONL line before conversion.
 98→// Used by agent-specific converters to normalize their format (e.g., Droid
 99→// envelope unwrapping) before the shared pipeline processes it.
100→type linePreprocessor func(map[string]json.RawMessage) map[string]json.RawMessage
101→
102→// compactJSONL converts JSONL transcripts (Claude Code, Cursor) into the
103→// compact format.
104→func compactJSONL(content []byte, opts Options) ([]byte, error) {
105→	return compactJSONLWith(content, opts, nil)
106→}
107→
108→// parsedEntry is an intermediate representation of a JSONL line used during
109→// the two-pass compact conversion.
110→type parsedEntry struct {
111→	kind         string // "user" or "assistant"
112→	ts           json.RawMessage
113→	id           string            // message ID (assistant only)
114→	userID       string            // prompt ID (user only, e.g. Claude's promptId)
115→	inputTokens  int               // API input tokens (assistant only)
116→	outputTokens int               // API output tokens (assistant only)
117→	content      json.RawMessage   // stripped assistant content array, or nil
118→	userText     string            // extracted user text
119→	userImages   []json.RawMessage // image blocks from user messages
120→	toolResults  []toolResultEntry // user tool_result entries
121→}
122→
123→// compactJSONLWith converts JSONL transcripts into the compact format.
124→// It uses a two-pass approach:
125→//  1. Parse all lines into intermediate entries
126→//  2. Merge streaming assistant fragments (same msg ID), inline tool results
127→//     from user lines into preceding assistant tool_use blocks, and drop
128→//     tool-result-only user lines.
129→func compactJSONLWith(content []byte, opts Options, preprocess linePreprocessor) ([]byte, error) {
130→	meta := newCompactMeta(opts)
131→
132→	// Pass 1: parse all lines into intermediate entries.
133→	entries, err := parseJSONLEntries(content, preprocess)
134→	if err != nil {
135→		return nil, err
136→	}
137→
138→	// Pass 2: merge and emit.
139→	var result []byte
140→	for i := 0; i < len(entries); i++ {
141→		e := entries[i]
142→
143→		switch e.kind {
144→		case transcript.TypeAssistant:
145→			// Merge consecutive assistant entries with the same message ID.
146→			merged := e
147→			for i+1 < len(entries) && entries[i+1].kind == transcript.TypeAssistant && entries[i+1].id == e.id {
148→				i++
149→				merged = mergeAssistantEntries(merged, entries[i])
150→			}
151→
152→			// Look ahead for user tool_result entries to inline.
153→			if i+1 < len(entries) && entries[i+1].kind == transcript.TypeUser && hasToolResults(entries[i+1]) {
154→				userEntry := entries[i+1]
155→				merged = inlineToolResults(merged, userEntry)
156→				i++ // consume the user tool_result entry
157→
158→				// If the consumed user entry also had text or image content, emit it
159→				// as a separate user line after the assistant.
160→				if userEntry.userText != "" || len(userEntry.userImages) > 0 {
161→					emitAssistant(&result, meta, merged)
162→					emitUser(&result, meta, userEntry)
163→					continue
164→				}
165→			}
166→
167→			if isEmptyContentArray(merged.content) {
168→				continue
169→			}
170→
171→			emitAssistant(&result, meta, merged)
172→
173→		case transcript.TypeUser:
174→			// User entries that are purely tool results were already consumed
175→			// by the assistant look-ahead above. If we reach one here it was
176→			// not preceded by an assistant with a matching tool_use, so emit
177→			// it only if it has text or image content.
178→			if hasToolResults(e) && e.userText == "" && len(e.userImages) == 0 {
179→				continue
180→			}
181→			emitUser(&result, meta, e)
182→		}
183→	}
184→
185→	return result, nil
186→}
187→
188→func emitAssistant(result *[]byte, meta compactMeta, e parsedEntry) {
189→	b := marshalOrdered(
190→		"v", meta.v,
191→		"agent", meta.agent,
192→		"cli_version", meta.cliVersion,
193→		"type", mustMarshal(transcript.TypeAssistant),
194→		"ts", e.ts,
195→		"id", jsonStringOrNil(e.id),
196→		"input_tokens", jsonIntOrNil(e.inputTokens),
197→		"output_tokens", jsonIntOrNil(e.outputTokens),
198→		"content", e.content,
199→	)
200→	*result = append(*result, b...)
201→	*result = append(*result, '\n')
202→}
203→
204→func emitUser(result *[]byte, meta compactMeta, e parsedEntry) {
205→	var blocks []json.RawMessage
206→
207→	// Text block (with optional prompt ID).
208→	if e.userText != "" || len(e.userImages) == 0 {
209→		block := marshalOrdered(
210→			"id", jsonStringOrNil(e.userID),
211→			"text", mustMarshal(e.userText),
212→		)
213→		blocks = append(blocks, block)
214→	}
215→
216→	// Image blocks passed through verbatim.
217→	blocks = append(blocks, e.userImages...)
218→
219→	contentJSON := mustMarshal(blocks)
220→
221→	b := marshalOrdered(
222→		"v", meta.v,
223→		"agent", meta.agent,
224→		"cli_version", meta.cliVersion,
225→		"type", mustMarshal(transcript.TypeUser),
226→		"ts", e.ts,
227→		"input_tokens", jsonIntOrNil(e.inputTokens),
228→		"output_tokens", jsonIntOrNil(e.outputTokens),
229→		"content", contentJSON,
230→	)
231→	*result = append(*result, b...)
232→	*result = append(*result, '\n')
233→}
234→
235→// parseJSONLEntries parses all JSONL lines into intermediate entries,
236→// filtering dropped types and malformed lines.
237→func parseJSONLEntries(content []byte, preprocess linePreprocessor) ([]parsedEntry, error) {
238→	reader := bufio.NewReader(bytes.NewReader(content))
239→	var entries []parsedEntry
240→
241→	for {
242→		lineBytes, err := reader.ReadBytes('\n')
243→		if err != nil && err != io.EOF {
244→			return nil, fmt.Errorf("reading JSONL line: %w", err)
245→		}
246→
247→		if len(bytes.TrimSpace(lineBytes)) > 0 {
248→			if e, ok := parseLine(lineBytes, preprocess); ok {
249→				entries = append(entries, e)
250→			}
251→		}
252→
253→		if err == io.EOF {
254→			break
255→		}
256→	}
257→
258→	return entries, nil
259→}
260→
261→// parseLine converts a single JSONL line into a parsedEntry.
262→// Returns ok=false for dropped/malformed lines.
263→func parseLine(lineBytes []byte, preprocess linePreprocessor) (parsedEntry, bool) {
264→	var raw map[string]json.RawMessage
265→	if err := json.Unmarshal(lineBytes, &raw); err != nil {
266→		return parsedEntry{}, false
267→	}
268→
269→	if preprocess != nil {
270→		raw = preprocess(raw)
271→	}
272→
273→	kind := normalizeKind(raw)
274→	if kind == "" {
275→		return parsedEntry{}, false
276→	}
277→
278→	e := parsedEntry{
279→		kind: kind,
280→		ts:   raw["timestamp"],
281→	}
282→
283→	msg := parseMessage(raw)
284→
285→	switch kind {
286→	case transcript.TypeAssistant:
287→		if msg != nil {
288→			e.id = unquote(msg["id"])
289→			if contentRaw, ok := msg["content"]; ok {
290→				e.content = stripAssistantContent(contentRaw)
291→			}
292→			e.inputTokens, e.outputTokens = extractUsageTokens(msg)
293→		}
294→
295→	case transcript.TypeUser:
296→		e.userID = unquote(raw["promptId"])
297→		if msg != nil {
298→			if contentRaw, ok := msg["content"]; ok {
299→				uc := extractUserContent(contentRaw)
300→				e.userText = uc.text
301→				e.userImages = uc.images
302→				e.toolResults = uc.toolResults
303→			}
304→		}
305→		// Enrich tool results with metadata from toolUseResult.
306→		if turRaw, ok := raw["toolUseResult"]; ok {
307→			var tur map[string]json.RawMessage
308→			if json.Unmarshal(turRaw, &tur) == nil {
309→				e.toolResults = enrichToolResults(e.toolResults, tur)
310→			}
311→		}
312→	}
313→
314→	return e, true
315→}
316→
317→// mergeAssistantEntries combines two assistant entries with the same message ID.
318→// Content arrays are concatenated; the later timestamp and token counts win
319→// (streaming fragments report cumulative usage, so the last fragment is final).
320→func mergeAssistantEntries(a, b parsedEntry) parsedEntry {
321→	merged := a
322→	merged.ts = b.ts
323→	if b.inputTokens > 0 {
324→		merged.inputTokens = b.inputTokens
325→	}
326→	if b.outputTokens > 0 {
327→		merged.outputTokens = b.outputTokens
328→	}
329→
330→	var aBlocks, bBlocks []json.RawMessage
331→	_ = json.Unmarshal(a.content, &aBlocks) //nolint:errcheck // best-effort merge
332→	_ = json.Unmarshal(b.content, &bBlocks) //nolint:errcheck // best-effort merge
333→	all := append(aBlocks, bBlocks...)      //nolint:gocritic // intentional append to new slice
334→	if data, err := json.Marshal(all); err == nil {
335→		merged.content = data
336→	}
337→
338→	return merged
339→}
340→
341→// inlineToolResults adds "result" fields to matching tool_use blocks in the
342→// assistant entry's content, using outputs from user tool_result entries.
343→func inlineToolResults(assistant, user parsedEntry) parsedEntry {
344→	var blocks []map[string]json.RawMessage
345→	if json.Unmarshal(assistant.content, &blocks) != nil || len(blocks) == 0 {
346→		return assistant
347→	}
348→
349→	for _, tr := range user.toolResults {
350→		// Find the tool_use block matching this tool_use_id.
351→		idx := -1
352→		for i := len(blocks) - 1; i >= 0; i-- {
353→			if unquote(blocks[i]["type"]) == transcript.ContentTypeToolUse {
354→				if tr.toolUseID == "" || unquote(blocks[i]["id"]) == tr.toolUseID {
355→					idx = i
356→					break
357→				}
358→			}
359→		}
360→		// No matching tool_use block: do not attach a result to unrelated content.
361→		if idx == -1 {
362→			continue
363→		}
364→
365→		blocks[idx]["result"] = buildToolResult(tr)
366→	}
367→
368→	if data, err := json.Marshal(blocks); err == nil {
369→		assistant.content = data
370→	}
371→
372→	return assistant
373→}
374→
375→// buildToolResult constructs the compact result object for a tool_use block,
376→// including optional rich metadata (file, matchCount) when available.
377→func buildToolResult(tr toolResultEntry) json.RawMessage {
378→	status := "success"
379→	if tr.isError {
380→		status = "error"
381→	}
382→
383→	// Build file metadata JSON if present.
384→	var fileJSON json.RawMessage
385→	if tr.file != nil {
386→		if tr.file.numLines > 0 {
387→			fileJSON = marshalOrdered(
388→				"filePath", mustMarshal(tr.file.filePath),
389→				"numLines", mustMarshal(tr.file.numLines),
390→			)
391→		} else {
392→			fileJSON = marshalOrdered(
393→				"filePath", mustMarshal(tr.file.filePath),
394→			)
395→		}
396→	}
397→
398→	// matchCount: only include if > 0.
399→	var matchCountJSON json.RawMessage
400→	if tr.matchCount > 0 {
401→		matchCountJSON = mustMarshal(tr.matchCount)
402→	}
403→
404→	return marshalOrdered(
405→		"output", mustMarshal(tr.output),
406→		"status", mustMarshal(status),
407→		"file", fileJSON,
408→		"matchCount", matchCountJSON,
409→	)
410→}
411→
412→// extractUsageTokens extracts input_tokens and output_tokens from a Claude
413→// message's "usage" object. Returns (0, 0) if usage is absent or malformed.
414→func extractUsageTokens(msg map[string]json.RawMessage) (inputTokens, outputTokens int) {
415→	usageRaw, ok := msg["usage"]
416→	if !ok {
417→		return 0, 0
418→	}
419→	var usage struct {
420→		InputTokens  int `json:"input_tokens"`
421→		OutputTokens int `json:"output_tokens"`
422→	}
423→	if json.Unmarshal(usageRaw, &usage) != nil {
424→		return 0, 0
425→	}
426→	return usage.InputTokens, usage.OutputTokens
427→}
428→
429→// jsonIntOrNil returns a JSON-encoded integer, or nil if n is zero.
430→func jsonIntOrNil(n int) json.RawMessage {
431→	if n == 0 {
432→		return nil
433→	}
434→	return mustMarshal(n)
435→}
436→
437→// jsonStringOrNil returns a JSON-encoded string, or nil if s is empty.
438→func jsonStringOrNil(s string) json.RawMessage {
439→	if s == "" {
440→		return nil
441→	}
442→	return mustMarshal(s)
443→}
444→
445→// isEmptyContentArray returns true if raw is a JSON empty array (`[]`).
446→func isEmptyContentArray(raw json.RawMessage) bool {
447→	var arr []json.RawMessage
448→	return json.Unmarshal(raw, &arr) == nil && len(arr) == 0
449→}
450→
451→func hasToolResults(e parsedEntry) bool {
452→	return len(e.toolResults) > 0
453→}
454→
455→type toolResultEntry struct {
456→	toolUseID string
457→	output    string
458→	isError   bool
459→	// Rich metadata extracted from toolUseResult (optional).
460→	file       *toolResultFile // Read/Edit: file path and line count
461→	matchCount int             // Grep: number of matching files
462→}
463→
464→// toolResultFile carries structured file metadata from Read/Edit tool results.
465→type toolResultFile struct {
466→	filePath string
467→	numLines int // 0 if not available (e.g. Edit results)
468→}
469→
470→// enrichToolResults extracts structured metadata from a toolUseResult envelope
471→// and attaches it to the corresponding tool result entries.
472→//
473→// Claude Code's toolUseResult has different shapes per tool:
474→//   - Bash:  {stdout, stderr, interrupted, ...}
475→//   - Read:  {type:"text", file:{filePath, numLines, content, ...}}
476→//   - Grep:  {numFiles, numLines, filenames, content, mode}
477→//   - Edit:  {filePath, oldString, newString, structuredPatch, ...}
478→func enrichToolResults(results []toolResultEntry, tur map[string]json.RawMessage) []toolResultEntry {
479→	// Bash-style: stdout provides the output text.
480→	if stdout := unquote(tur["stdout"]); stdout != "" {
481→		switch len(results) {
482→		case 0:
483→			// Keep compatibility with transcripts that only include toolUseResult.
484→			results = append(results, toolResultEntry{output: stdout})
485→		case 1:
486→			results[0].output = stdout
487→		}
488→	}
489→
490→	// Read-style: file object with filePath and numLines.
491→	if fileRaw, ok := tur["file"]; ok {
492→		var file struct {
493→			FilePath string `json:"filePath"`
494→			NumLines int    `json:"numLines"`
495→		}
496→		if json.Unmarshal(fileRaw, &file) == nil && file.FilePath != "" {
497→			applyToSingleResult(results, func(tr *toolResultEntry) {
498→				tr.file = &toolResultFile{filePath: file.FilePath, numLines: file.NumLines}
499→			})
500→		}
501→	}
502→
503→	// Edit-style: top-level filePath.
504→	if filePath := unquote(tur["filePath"]); filePath != "" {
505→		applyToSingleResult(results, func(tr *toolResultEntry) {
506→			// Edit results don't have numLines.
507→			tr.file = &toolResultFile{filePath: filePath}
508→		})
509→	}
510→
511→	// Grep-style: numFiles as match count.
512→	if numFilesRaw, ok := tur["numFiles"]; ok {
513→		var n int
514→		if json.Unmarshal(numFilesRaw, &n) == nil && n > 0 {
515→			applyToSingleResult(results, func(tr *toolResultEntry) {
516→				tr.matchCount = n
517→			})
518→		}
519→	}
520→
521→	return results
522→}
523→
524→// applyToSingleResult applies fn to the first (and expected only) tool result.
525→// toolUseResult is a single-tool envelope, so this is only meaningful when
526→// there's exactly one result entry.
527→func applyToSingleResult(results []toolResultEntry, fn func(*toolResultEntry)) {
528→	if len(results) == 1 {
529→		fn(&results[0])
530→	}
531→}
532→
533→// parseMessage extracts and parses the "message" field from a JSONL transcript
534→// line. All JSONL agents nest content inside a "message" object.
535→func parseMessage(raw map[string]json.RawMessage) map[string]json.RawMessage {
536→	msgRaw, ok := raw["message"]
537→	if !ok {
538→		return nil
539→	}
540→	var msg map[string]json.RawMessage
541→	if json.Unmarshal(msgRaw, &msg) == nil {
542→		return msg
543→	}
544→	return nil
545→}
546→
547→// userContent holds the extracted parts of a user message content array.
548→type userContent struct {
549→	text        string
550→	images      []json.RawMessage
551→	toolResults []toolResultEntry
552→}
553→
554→// extractUserContent separates user message content into text, images, and tool_result entries.
555→// IDE context tags (e.g. <user_query>, <ide_opened_file>) are stripped from user text.
556→func extractUserContent(contentRaw json.RawMessage) userContent {
557→	var str string
558→	if json.Unmarshal(contentRaw, &str) == nil {
559→		return userContent{text: textutil.StripIDEContextTags(str)}
560→	}
561→
562→	var blocks []json.RawMessage
563→	if json.Unmarshal(contentRaw, &blocks) != nil {
564→		return userContent{}
565→	}
566→
567→	var uc userContent
568→
569→	for _, blockRaw := range blocks {
570→		var block map[string]json.RawMessage
571→		if json.Unmarshal(blockRaw, &block) != nil {
572→			continue
573→		}
574→		blockType := unquote(block["type"])
575→
576→		switch blockType {
577→		case "tool_result":
578→			var isErr bool
579→			if raw, ok := block["is_error"]; ok {
580→				_ = json.Unmarshal(raw, &isErr) //nolint:errcheck // best-effort
581→			}
582→			uc.toolResults = append(uc.toolResults, toolResultEntry{
583→				toolUseID: unquote(block["tool_use_id"]),
584→				output:    unquote(block["content"]),
585→				isError:   isErr,
586→			})
587→
588→		case "image":
589→			uc.images = append(uc.images, blockRaw)
590→
591→		case transcript.ContentTypeText:
592→			stripped := textutil.StripIDEContextTags(unquote(block[transcript.ContentTypeText]))
593→			if stripped != "" {
594→				uc.text += stripped + "\n\n"
595→			}
596→		}
597→	}
598→
599→	uc.text = strings.TrimSpace(uc.text)
600→	return uc
601→}
602→
603→func stripAssistantContent(contentRaw json.RawMessage) json.RawMessage {
604→	var str string
605→	if json.Unmarshal(contentRaw, &str) == nil {
606→		return contentRaw
607→	}
608→
609→	var blocks []map[string]json.RawMessage
610→	if json.Unmarshal(contentRaw, &blocks) != nil {
611→		return contentRaw
612→	}
613→
614→	result := make([]map[string]json.RawMessage, 0, len(blocks))
615→	for _, block := range blocks {
616→		blockType := unquote(block["type"])
617→
618→		if blockType == "thinking" || blockType == "redacted_thinking" {
619→			continue
620→		}
621→
622→		if blockType == transcript.ContentTypeToolUse {
623→			stripped := make(map[string]json.RawMessage)
624→			copyField(stripped, block, "type")
625→			copyField(stripped, block, "id")
626→			copyField(stripped, block, "name")
627→			copyField(stripped, block, "input")
628→			result = append(result, stripped)
629→			continue
630→		}
631→
632→		result = append(result, block)
633→	}
634→
635→	b, err := json.Marshal(result)
636→	if err != nil {
637→		return contentRaw
638→	}
639→	return b
640→}
641→
642→// marshalOrdered produces a JSON object with keys in the given order.
643→// Pairs with nil values are omitted.
644→func marshalOrdered(pairs ...interface{}) []byte {
645→	var buf bytes.Buffer
646→	buf.WriteByte('{')
647→	first := true
648→	for i := 0; i < len(pairs)-1; i += 2 {
649→		key := pairs[i].(string)               //nolint:errcheck,forcetypeassert // contract: keys are always strings
650→		val, _ := pairs[i+1].(json.RawMessage) //nolint:errcheck // nil val is handled below
651→		if val == nil {
652→			continue
653→		}
654→		if !first {
655→			buf.WriteByte(',')
656→		}
657→		keyJSON, _ := json.Marshal(key) //nolint:errcheck,errchkjson // string keys never fail
658→		buf.Write(keyJSON)
659→		buf.WriteByte(':')
660→		buf.Write(val)
661→		first = false
662→	}
663→	buf.WriteByte('}')
664→	return buf.Bytes()
665→}
666→
667→// mustMarshal marshals v to JSON, panicking on error (which should never
668→// happen for the primitive types we pass).
669→func mustMarshal(v interface{}) json.RawMessage {
670→	b, _ := json.Marshal(v) //nolint:errcheck,errchkjson // only used with primitive types that never fail
671→	return b
672→}
673→
674→// copyField copies a single key from src to dst if it exists.
675→func copyField(dst, src map[string]json.RawMessage, key string) {
676→	if v, ok := src[key]; ok {
677→		dst[key] = v
678→	}
679→}
