 13→// --- OpenCode format support ---
 14→//
 15→// OpenCode transcripts are a single JSON object (not JSONL):
 16→//
 17→//	{"info":{...},"messages":[{"info":{"role":"user","time":{...}},"parts":[...]}, ...]}
 18→//
 19→// Parts use "type" values: "text", "tool", "step-start", "step-finish".
 20→// Tool parts store the tool name in "tool" (string) and call details in "state".
 21→
 22→// isOpenCodeFormat checks whether content is a single JSON object with the
 23→// OpenCode session shape (top-level "info" and "messages" keys).
 24→func isOpenCodeFormat(content []byte) bool {
 25→	trimmed := bytes.TrimSpace(content)
 26→	if len(trimmed) == 0 || trimmed[0] != '{' {
 27→		return false
 28→	}
 29→	// Quick structural check: unmarshal just enough to detect the keys.
 30→	var probe struct {
 31→		Info     *json.RawMessage `json:"info"`
 32→		Messages *json.RawMessage `json:"messages"`
 33→	}
 34→	if json.Unmarshal(trimmed, &probe) != nil {
 35→		return false
 36→	}
 37→	return probe.Info != nil && probe.Messages != nil
 38→}
