 40→// openCodeMessage mirrors the OpenCode message structure for unmarshaling.
 41→type openCodeMessage struct {
 42→	Info  openCodeMessageInfo          `json:"info"`
 43→	Parts []map[string]json.RawMessage `json:"parts"`
 44→}
 45→
 46→type openCodeMessageInfo struct {
 47→	ID     string            `json:"id"`
 48→	Role   string            `json:"role"`
 49→	Time   openCodeMsgTime   `json:"time"`
 50→	Tokens *openCodeMsgToken `json:"tokens"`
 51→}
