 63→// compactOpenCode converts a full OpenCode session JSON into transcript lines.
 64→func compactOpenCode(content []byte, opts Options) ([]byte, error) {
 65→	var session struct {
 66→		Messages []openCodeMessage `json:"messages"`
 67→	}
 68→	if err := json.Unmarshal(bytes.TrimSpace(content), &session); err != nil {
 69→		return nil, fmt.Errorf("parsing opencode session: %w", err)
 70→	}
 71→
 72→	meta := newCompactMeta(opts)
 73→	var result []byte
 74→
 75→	for _, msg := range session.Messages {
 76→		ts := msToTimestamp(msg.Info.Time.Created)
 77→
 78→		switch msg.Info.Role {
 79→		case transcript.TypeUser:
 80→			lines := convertOpenCodeUser(msg, ts, meta)
 81→			for _, l := range lines {
 82→				result = append(result, l...)
 83→				result = append(result, '\n')
 84→			}
 85→		case transcript.TypeAssistant:
 86→			lines := convertOpenCodeAssistant(msg, ts, meta)
 87→			for _, l := range lines {
 88→				result = append(result, l...)
 89→				result = append(result, '\n')
 90→			}
 91→		}
 92→	}
 93→
 94→	return result, nil
 95→}
