 97→func convertOpenCodeUser(msg openCodeMessage, ts json.RawMessage, meta compactMeta) [][]byte {
 98→	content := make([]map[string]json.RawMessage, 0, len(msg.Parts))
 99→
100→	for _, part := range msg.Parts {
101→		if unquote(part["type"]) != transcript.ContentTypeText {
102→			continue
103→		}
104→		text := textutil.StripIDEContextTags(unquote(part[transcript.ContentTypeText]))
105→		if text == "" {
106→			continue
107→		}
108→		block := map[string]json.RawMessage{
109→			"text": mustMarshal(text),
110→		}
111→		if id := part["id"]; id != nil {
112→			block["id"] = id
113→		}
114→		content = append(content, block)
115→	}
116→
117→	contentJSON, err := json.Marshal(content)
118→	if err != nil {
119→		return nil
120→	}
121→
122→	b := marshalOrdered(
123→		"v", meta.v,
124→		"agent", meta.agent,
125→		"cli_version", meta.cliVersion,
126→		"type", mustMarshal(transcript.TypeUser),
127→		"ts", ts,
128→		"content", json.RawMessage(contentJSON),
129→	)
130→	return [][]byte{b}
131→}
