133→func convertOpenCodeAssistant(msg openCodeMessage, ts json.RawMessage, meta compactMeta) [][]byte {
134→	content := make([]map[string]json.RawMessage, 0, len(msg.Parts))
135→
136→	for _, part := range msg.Parts {
137→		partType := unquote(part["type"])
138→
139→		switch partType {
140→		case transcript.ContentTypeText:
141→			content = append(content, map[string]json.RawMessage{
142→				"type": mustMarshal(transcript.ContentTypeText),
143→				"text": part[transcript.ContentTypeText],
144→			})
145→		case "tool":
146→			toolBlock := make(map[string]json.RawMessage)
147→			toolBlock["type"] = mustMarshal(transcript.ContentTypeToolUse)
148→			if callID := part["callID"]; callID != nil {
149→				toolBlock["id"] = callID
150→			}
151→			if toolName := part["tool"]; toolName != nil {
152→				toolBlock["name"] = toolName
153→			}
154→			if stateRaw := part["state"]; stateRaw != nil {
155→				var state map[string]json.RawMessage
156→				if json.Unmarshal(stateRaw, &state) == nil {
157→					if inp := state["input"]; inp != nil {
158→						toolBlock["input"] = inp
159→					}
160→					toolBlock["result"] = openCodeToolResult(state)
161→				}
162→			}
163→			content = append(content, toolBlock)
164→		}
165→	}
166→
167→	contentJSON, err := json.Marshal(content)
168→	if err != nil {
169→		return nil
170→	}
171→
172→	var inputTok, outputTok int
173→	if msg.Info.Tokens != nil {
174→		inputTok = msg.Info.Tokens.Input
175→		outputTok = msg.Info.Tokens.Output
176→	}
177→
178→	b := marshalOrdered(
179→		"v", meta.v,
180→		"agent", meta.agent,
181→		"cli_version", meta.cliVersion,
182→		"type", mustMarshal(transcript.TypeAssistant),
183→		"ts", ts,
184→		"id", mustMarshal(msg.Info.ID),
185→		"input_tokens", jsonIntOrNil(inputTok),
186→		"output_tokens", jsonIntOrNil(outputTok),
187→		"content", json.RawMessage(contentJSON),
188→	)
189→	return [][]byte{b}
190→}
