192→// openCodeToolResult builds the compact {"output":"...","status":"success"|"error"}
193→// object from an OpenCode tool state map.
194→func openCodeToolResult(state map[string]json.RawMessage) json.RawMessage {
195→	status := "success"
196→	if s := unquote(state["status"]); s != "" && s != "completed" {
197→		status = "error"
198→	}
199→	result := map[string]string{
200→		"output": unquote(state["output"]),
201→		"status": status,
202→	}
203→	return mustMarshal(result)
204→}
