206→// msToTimestamp converts a Unix millisecond timestamp to an RFC3339 JSON string.
207→func msToTimestamp(ms int64) json.RawMessage {
208→	if ms == 0 {
209→		return nil
210→	}
211→	t := time.UnixMilli(ms).UTC()
212→	return mustMarshal(t.Format(time.RFC3339Nano))
213→}
